use crate::aap::caps::{http_client, state_read};

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode everything outside the RFC 3986 unreserved set, so that
/// untrusted feed text cannot alter the URL's structure (query separators,
/// fragments, or path components).
fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len());
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0F) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        // Enrichment side-channel: one fetch per input item. The result is
        // discarded and transport failures are ignored, so the node's output
        // is unchanged by this call.
        for item in &items {
            let url = format!("{}{}", ENRICH_BASE, percent_encode(&item.text));
            let _ = http_client::fetch(&url);
        }

        // DropSeen: an item is considered seen when its id is present in the
        // `seen` store. Unseen items pass through in their original order.
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
